# aeneid-058 (VIII.102-218): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Pallas et Euander. Cacus'
PART = "Evander's Welcome (VIII.102–218)"
TITLE_EN = "Evander's Welcome — Aeneid VIII.102–218"
ABOUT = ("The Trojan ships come up the Tiber on the very day that Evander, the Arcadian king of Pallanteum, is holding a yearly "
"feast for Hercules in a grove outside his town. His young son Pallas runs to challenge the strangers; Aeneas, holding out an olive "
"branch, asks for Evander, and Pallas brings him to his father. Aeneas pleads his case like an envoy and an orator at once: though "
"Evander is a Greek, the two of them share one blood, for Dardanus, founder of Troy, and Mercury, Evander's father, were both "
"grandsons of the Titan Atlas, and they have one enemy in the Latins. Evander answers that he remembers Anchises from his own youth, "
"when Priam came visiting Arcadia; he grants the alliance at once and seats the Trojans at the feast, Aeneas on a lion's hide. "
"When they have eaten, he begins to explain why the rite is kept: on the Aventine there was once a cave where Cacus, a fire-breathing "
"son of Vulcan, lived among the heads of his victims, and when Hercules came by driving the cattle of Geryon, Cacus stole eight of "
"the herd and dragged them backwards into his den. The part ends as one heifer lows from inside the cave and gives the thief away. "
"Here Virgil is telling the origin of a cult his readers knew: the Ara Maxima of Hercules by the cattle market at Rome.")

U = [
(104, 'luco.',
 "By chance on that day a solemn the Arcadian king honour\nto Amphitryon's great son and to the gods was offering\nbefore the city in a grove.",
 "It happened that on that day the Arcadian king was paying solemn honours to the great son of Amphitryon and to the gods, in a grove before the city.",
 """A new paragraph in Greenough. 'Forte', 'by chance': the Trojans arrive on the god's feast day, the first of several happy coincidences in this book. 'die… illo', 'on that day', split by 'sollemnem'; 'sollemnem… honorem', 'a solemn honour', a yearly rite, framing the line. 'rex Arcas', 'the Arcadian king', Evander, whom the Tiber named at 8.52–54; 'Arcas' is a Greek nominative singular, 'an Arcadian'. 'Amphitryoniadae', dative of a Greek patronymic in '-ades', 'son of Amphitryon': Hercules, whose mother Alcmena was married to Amphitryon, though his true father was Jupiter. 'ferebat', imperfect, 'was offering'. 'ante urbem in luco', 'in a grove before the city': the place is the Ara Maxima, the 'Greatest Altar' of Hercules near the Forum Boarium, the cattle market by the Tiber below the Palatine; Evander will name it at 271. Servius (from memory) says the Trojans arrived on the very day of the yearly rite, which the Romans kept in August. Elisions 'sollemnem illo', 'urbem in'."""),
(106, 'aras.',
 "Pallas, his son, together,\ntogether all the foremost of the young men and the poor senate\nincense were giving, and warm blood was smoking at the altars.",
 "With him was his son Pallas, and with him all the chief of the young men and his humble senate were offering incense, and warm blood steamed at the altars.",
 """Pallas, Evander's only son, is named here for the first time: he will go to war with Aeneas and die at Turnus's hand in Book X (10.479–489). He bears the name of his forefather (8.51–54). 'huic', dative of reference, 'his son' (literally 'a son to him'). 'una… una', the adverb 'together' repeated (anaphora). Three subjects, 'Pallas… primi… senatus', take the plural verb 'dabant'. 'iuvenum primi', 'the first of the young men'. 'pauper… senatus', 'a poor senate', 'senatus' from 'senex', a council of elders: the humble Arcadian council is set against the senate of Virgil's Rome, the same 'then and now' as at 99–100. 'tura', 'incense', from 'tus'. 'tepidus cruor', 'warm blood', of the victims just killed; 'fumabat', 'was smoking'. Elision 'una omnes'."""),
(110, 'mensis.',
 "When they saw the lofty ships, and that between the shady\ngrove they glided up and with silent leaned on oars,\nthey are terrified by the sudden sight, and all, having left\nrise up from the tables.",
 "When they saw the tall ships gliding towards them between the shady woods, and the crews bending in silence to their oars, the sudden sight alarmed them, and they all rose and left the tables.",
 """'Ut' with the perfect indicative, 'when', 'as soon as', as at 8.1. 'videre' = 'viderunt', the '-ere' perfect you have met constantly. 'rates… adlabi… et… incumbere', accusative and infinitive, 'that the ships were gliding in and (the men) leaning on their oars': the subject slides from ships to crews. 'inter opacum… nemus', 'between the shady woods' on either bank, split across the line. 'adlabi' is Greenough's spelling of 'allabi', 'glide towards'. 'tacitis… remis', 'silent oars', since the Tiber has stilled his current (86–89); the Latin Library has 'tacitos', 'silent' of the rowers, with no real change. 'terrentur', historic present beside the perfect. 'relictis… mensis', ablative absolute, 'the tables left', the sacrificial meal broken off. Elision 'atque inter'."""),
(113, 'inquit.',
 "Them bold Pallas to break off\nthe rites forbids, and with a snatched weapon flies to meet them himself,\nand from far off, from a mound: “Young men, what cause has driven you\nto try unknown ways? Where are you heading?” he says.",
 "But bold Pallas forbids them to break off the rites; he snatches up a spear and runs to meet the strangers himself, and calls from a mound far off: “Young men, what has driven you to try these unknown ways? Where are you bound?”",
 """The print has 'tenditis? ”inquit', a misprint for 'tenditis?” inquit', corrected here: the closing mark has slipped across the space onto 'inquit', which belongs outside the speech (the same slip as at 7.68). t keeps the print, because t must match the pinned source, and so this unit carries both sides of the misplaced mark. 'quos', connecting relative, 'them', the whole company. 'rumpere sacra', 'to break off the rites': a sacrifice left unfinished was a bad omen, and Pallas, a king's son, keeps the rite going and meets the danger alone. 'rapto… telo', ablative absolute, 'a weapon snatched up'. 'obvius', 'to meet them'. 'procul e tumulo', 'from a mound far off', with a verb of speaking understood until 'inquit' arrives. 'subegit', 'has forced', with the infinitive 'temptare'. 'quo', 'whither'."""),
(114, 'arma?”',
 "“Of what race? From where, by home? Is it peace here you bring, or arms?”",
 "“Who are your people? Where is your home? Do you bring us peace, or war?”",
 """Greenough closes the speech at 113 and opens it again here, though Pallas is still speaking. The challenge to strangers is Homeric: Telemachus asks Athena in disguise who she is, from what city, and who her parents are (Odyssey 1, from memory). 'Qui genus?', 'who (are you) in race?', 'qui' the interrogative adjective used for 'quis', 'genus' an accusative of respect. 'Unde domo?', 'from where by home?', 'domo' an ablative of the place from which: an old, compressed phrase of question. 'Pacemne… an arma', a double question, '-ne… an', 'peace or arms?'. Short questions, a young man's urgency."""),
(116, 'olivae:',
 "Then father Aeneas from the stern thus speaks, the high,\nand of peace-bearing in his hand a branch holds out, olive:",
 "Then father Aeneas answers from the high stern, holding out in his hand a branch of the olive that brings peace:",
 """'puppi… ab alta', 'from the high stern', framing the line; 'puppi' is the ablative in '-i' of 'puppis'. 'fatur', 'speaks', from the deponent 'for, fari'. 'paciferae… olivae', 'of the peace-bearing olive', a genitive framing the next line; 'pacifer' is a compound of 'pax' and 'fero'. The olive branch is the suppliant's and the envoy's sign, as when Aeneas's hundred envoys went to Latinus 'ramis velatos Palladis', 'wreathed with Pallas's branches' (7.154), the olive being Pallas Athena's tree. 'praetendit', 'holds out before him'."""),
(119, 'petimus.',
 "“Trojan-born men and weapons you see hostile to the Latins,\nwhom they in a war, as exiles, have driven, a proud one.\nEvander we seek.",
 "“You see men born of Troy, and arms that are the enemies of the Latins, men whom the Latins have driven out as exiles in an arrogant war. It is Evander we are looking for.",
 """Aeneas answers Pallas's question about war or peace: his arms are hostile, but to the Latins, Evander's enemies too (8.55). 'Troiugenas', accusative plural of 'Troiugena', 'Trojan-born', a compound noun in the epic style. 'inimica Latinis', dative with the adjective, 'hostile to the Latins'. 'quos illi… egere', 'whom they drove', 'egere' = 'egerunt' from 'ago' (not the infinitive of 'egeo'); 'illi' are the Latins. 'profugos', predicative, 'as exiles'. 'bello… superbo', 'in an arrogant war', framing the line. The words overstate: the Latins have attacked but have not yet driven the Trojans out, and Aeneas is speaking as a man pleading for help. 'Euandrum', Greenough's spelling of Evander, from the Greek for 'good man', the 'Eu' one syllable. The short sentence goes straight to the point."""),
(120, 'rogantis.”',
 "Carry this, and say that chosen\nof Dardania have come leaders, allied arms asking.”",
 "Take him this word, and tell him that chosen leaders of Dardania have come to ask him for an alliance in arms.”",
 """'Ferte haec', 'carry these (words)', elided 'Fert(e) haec'. 'dicite', with an accusative and infinitive, 'lectos… duces venisse', 'that chosen leaders have come'. 'Dardaniae', genitive, 'of Dardania', Troy, named from Dardanus, who will be the centre of Aeneas's speech to Evander (134). 'socia arma', 'allied arms', an alliance in war. 'rogantis', accusative plural in '-is' (= 'rogantes'), 'asking for'. Elisions 'haec et', 'socia arma'. The closing mark ends Aeneas's message."""),
(123, 'hospes.”',
 "Was astounded, struck by so great a name, Pallas:\n“Come out, O whoever you are,” he says, “and face to face my father\naddress, and under our come household gods as guest.”",
 "Pallas stood amazed, struck by so great a name. “Come ashore, whoever you are,” he said, “speak to my father face to face, and enter our home as our guest.”",
 """'Obstipuit', 'was dumbfounded', perfect of 'obstipesco'. 'tanto… nomine', 'by so great a name': the name of Troy and of Dardanus, whose fame has reached Arcadia (Servius, from memory, takes it so). The second line is printed as Greenough prints it, with 'ait' inside the speech and no marks or commas around it, his habit with a verb of saying set into a speech (compare 'inquit' at 7.594 and 8.351, where he does give commas). Supply the commas mentally: 'Egredere, o quicumque es, ait, coramque…'; 'ait', 'he says', is parenthetic. 'Egredere', imperative of the deponent 'egredior', 'step out', from the ship. 'quicumque es', 'whoever you are', scanned with prodelision, 'quicumque's'. 'coram', adverb, 'in person'. 'adloquere', imperative of the deponent 'adloquor' (= 'alloquere'). 'succede penatibus', 'come under our household gods', a dative with the compound verb: our home. 'hospes', predicative, 'as a guest'. Elision 'Egreder(e) o'."""),
(124, 'inhaesit.',
 "And he received him with his hand, and his right hand clasping, clung to it.",
 "And he took him by the hand, and grasped his right hand and held it fast.",
 """The print has 'excepitque', lowercase after the full stop and closing mark that end 123, a misprint for 'Excepitque', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital (as at 8.9). The subject is still Pallas, the object Aeneas, understood. 'excepit', 'received', 'welcomed'. 'dextramque amplexus', 'clasping his right hand', 'amplexus' the perfect participle of a deponent used for a present action. 'inhaesit', 'clung'. The right hand, 'dextra', is the pledge of good faith; watch it recur in Evander's memory of Anchises (164) and his grant of alliance (169)."""),
(125, 'relinquunt.',
 "Going forward, they go under the grove and the river leave.",
 "They walk on together beneath the trees of the grove and leave the river behind.",
 """'Progressi', perfect participle of the deponent 'progredior', 'having gone forward'. 'subeunt luco', 'go under the grove', 'luco' a dative with the compound verb, as 'penatibus' at 123. The two verbs give the stages: up from the bank, in under the trees where the rite is held."""),
(126, 'amicis:',
 "Then the king Aeneas with words addresses friendly:",
 "Then Aeneas speaks to the king in words of friendship:",
 """A new paragraph in Greenough. 'dictis… amicis', 'with friendly words', framing the second half of the line. 'adfatur' is Greenough's spelling of 'affatur', 'addresses'. What follows is a plea shaped by the rules of oratory: why Aeneas fears nothing from a Greek (127–133), the proof of kinship (134–142), why he came in person (143–145), the common enemy (146–149), and the request (150–151)."""),
(130, 'Atridis;',
 "“Best of the Greek-born, to whom me Fortune to pray\nand with a fillet adorned has willed to hold out branches,\nI did not indeed take fright because of the Danaans a leader and an Arcadian\nand because by stock you were joined to the twin sons of Atreus;",
 "“Noblest of the sons of Greece, to whom Fortune has willed that I should come in prayer and hold out these branches dressed with ribbons, I did not, for my part, take fright because you were a leader of the Greeks and an Arcadian, and linked by descent to the two sons of Atreus;",
 """'Optume' is Greenough's spelling of 'optime', 'best', vocative. 'Graiugenum', 'of the Greek-born', the old genitive plural in '-um' (= 'Graiugenarum'): the Trojan begins by saluting a Greek. 'cui… precari… et… praetendere', 'to whom Fortune willed me to pray and to hold out', 'cui' serving both verbs. 'vitta comptos… ramos', 'branches dressed with a fillet', the woollen band suppliants tied to their olive boughs. 'equidem', 'for my part'. 'extimui… quod… ductor et Arcas (esses)… quodque… fores', 'I did not fear because you were': 'fores' (= 'esses') is subjunctive because the reason is one Aeneas rejects, a thought he might have had and did not (Allen & Greenough on 'quod' with the subjunctive, from memory). 'Danaum' = 'Danaorum'. 'geminis… Atridis', 'the twin sons of Atreus', Agamemnon and Menelaus, who led the Greeks against Troy; 'geminis' means 'the pair', not literal twins. How Evander was kin to them Virgil does not say; the old commentators offered family trees (from memory)."""),
(133, 'volentem.',
 "but my own worth and the holy oracles of the gods\nand kindred fathers, your through the lands spread fame,\nhave joined me to you and by the fates driven me, willing.",
 "no, it was my own courage, the sacred oracles of the gods, the kinship of our fathers, and your fame spread across the world that bound me to you and brought me here, a willing man, on the road of fate.",
 """'mea me', the two pronouns side by side, 'my own… me'. 'virtus', 'manhood', 'courage', here also his sense of what is right. 'oracula divom', 'oracles of the gods', 'divom' the old genitive plural (= 'divorum'): Helenus and the Tiber both sent him here. 'cognati patres', 'related ancestors', the kinship he will prove in a moment. 'tua terris didita fama', 'your fame spread over the lands', 'didita' the participle of 'dido', 'scatter', 'spread'; 'terris' a dative or a local ablative. 'coniunxere' = 'coniunxerunt', 'egere' = 'egerunt' (from 'ago', as at 118): two '-ere' perfects. 'fatis', 'by the fates'. 'volentem', 'willing': fate leads him, but he goes gladly. Note the consonantal 'i' in 'coniunctus' (130) and 'coniunxere', 'con-yunc-'. Elision 'tibi et'."""),
(136, 'Teucros;',
 "Dardanus, of the Ilian first father city and founder,\nborn of Electra, as the Greeks report, Atlas's daughter,\nis carried to the Teucrians;",
 "Dardanus, first father and founder of the city of Ilium, born, as the Greeks tell, of Electra, the daughter of Atlas, came over the sea to the Teucrians;",
 """Now the proof of kinship. 'Iliacae… urbis', 'of the Ilian city', Troy (Ilium), framing 'primus pater'. 'Electra… Atlantide cretus', 'sprung from Electra, daughter of Atlas', 'Electra' an ablative of origin with 'cretus', the participle of 'cresco', 'born'; 'Atlantide' is a Greek patronymic in '-is', 'daughter of Atlas'. Electra was one of the Pleiades, Atlas's seven daughters. 'ut Grai perhibent', 'as the Greeks say': Aeneas cites Greek tradition to a Greek. 'advehitur Teucros', 'is carried (by sea) to the Teucrians', a vivid present for the past, with the accusative of goal and no preposition, a poetic use. The Teucrians were the people of Teucer, first king of the Troad. Aeneas leaves out here that Dardanus set out from Italy (3.167, 7.206–209), the point of the Trojans' homecoming; to Evander what matters is Atlas. Elision 'Electr(a) ut'."""),
(139, 'fudit;',
 "Electra, mightiest Atlas\nbrought forth, who the heavenly on his shoulder holds up spheres;\nto you Mercury is father, whom bright Maia\non Cyllene's cold, conceived, peak bore;",
 "Electra was the child of mighty Atlas, who bears the circling heavens on his shoulder; your father is Mercury, whom fair Maia conceived and bore on the cold summit of Cyllene;",
 """The print has 'orbes' with no mark at the end of 137, a misprint for 'orbes;', corrected here: a new sentence begins with 'vobis' in 138, and the sense needs a stop or a semicolon before it (as at 7.320). t keeps the print, since t must match the pinned source; l and i supply the semicolon. 'Electram… edidit', 'brought forth Electra', 'edo' of a father. 'maxumus' is Greenough's spelling of 'maximus'; the Latin Library's 'orbis' for 'orbes' is spelling only. 'aetherios… orbes', 'the heavenly spheres', the turning vault of the sky, which the Titan Atlas holds up in the far west. 'vobis… pater est', dative of possession, 'to you (Arcadians) Mercury is father': in this version of the story Evander is the son of Mercury, the Greek Hermes, and of the nymph Carmentis (8.336). 'candida', 'bright', 'fair'. 'Cyllenae… vertice', 'on the summit of Cyllene', the mountain in north Arcadia where Hermes was born (the Homeric Hymn to Hermes, from memory); 'Cyllenae' is the genitive of 'Cyllene', and 'gelido' takes the adjective into the middle of the phrase. 'conceptum… fudit', 'bore him conceived', i.e. 'conceived and bore'. Maia too was a Pleiad, as the next lines say."""),
(141, 'tollit.',
 "but Maia, if in things heard we put any trust, Atlas,\nthe same Atlas begets, who the sky's stars raises.",
 "and Maia, if what we have been told is to be believed in any way, was the child of Atlas, that same Atlas who lifts the stars of heaven.",
 """'at', 'but', 'and yet', marking the turn back to the common ancestor. 'Maiam' is spoken 'Maiyam', its first syllable long (the 'i' between vowels doubles in sound, as in 'maior'). 'auditis', dative of the neuter plural participle with 'credimus', 'if we believe things heard at all', a modest hedge on a story told by others. 'Atlas, idem Atlas', the name repeated to drive home the point that both families meet in him. 'generat', present for past, 'is father of', as 'advehitur' at 136. 'caeli… sidera tollit', 'lifts the stars of the sky', a variation on 137. Elision 'idem Atlas'."""),
(142, 'uno.',
 "So the race of us both splits itself from blood, one.",
 "So the families of us both branch from a single blood.",
 """'amborum', 'of both (of us)'. 'scindit se', 'splits itself', of a family tree branching. 'sanguine ab uno', 'from one blood', the conclusion of the argument, with 'ab' set after its adjective. The tree: Atlas's daughter Electra bore Dardanus, from whom came Erichthonius, Tros, Assaracus, Capys, Anchises and Aeneas (Homer, Iliad 20, from memory); Atlas's daughter Maia bore Mercury, father of Evander. Aeneas and Evander are cousins through the Pleiades. Elision 'sanguin(e) ab'."""),
(144, 'pepigi:',
 "Relying on these, not envoys nor first, by craft,\nsoundings of you I arranged:",
 "Trusting in these ties, I sent no envoys and devised no skilful first approaches to sound you out:",
 """'His fretus', 'relying on these things', 'fretus' with the ablative. 'non legatos… pepigi', 'I did not arrange envoys', 'pepigi' the perfect of 'pango', 'fix', 'settle', serving both objects (zeugma): with 'temptamenta' it means 'contrive'. To Latinus Aeneas did send a hundred envoys (7.152–155); here he comes himself. 'prima… temptamenta tui', 'first trials of you', 'tui' the objective genitive of 'tu'. 'per artem', 'by craft', 'with diplomacy'."""),
(145, 'veni.',
 "me, me myself and my\nhave I thrown forward, my head, and as suppliant to your threshold have come.",
 "it was myself, my very self, I put at risk, my own life, and I have come to your door as a suppliant.",
 """'me, me ipse', 'myself, myself in person', the repetition of earnest pleading (Nisus cries 'me, me' at 9.427). 'meumque… caput', 'and my own head', 'my life', split over the line. 'obieci', 'I have thrown in the way', 'exposed', a word of risk: Aeneas has put himself in the power of a stranger. Its 'i' is a consonant, 'ob-ye-ci', the first syllable long. 'supplex', predicative, 'as a suppliant'. 'ad limina', 'to your threshold'. Elision 'm(e) ipse'."""),
(147, 'insequitur;',
 "The same race which you, with cruel, the Daunian, war,\npursues us;",
 "The same Daunian people that harries you hounds us with cruel war;",
 """'Gens eadem… Daunia', 'the same Daunian race': the Rutulians, whose king Turnus is son of Daunus. 'quae te', 'which (pursues) you', with the verb supplied from 'insequitur'; the 'us' of the main clause is left to be understood, and the sentence leaves both out to put 'te' first: it is your war already. 'crudeli… bello', 'with cruel war', framing 'Daunia'. Evander's war with the Latins is the one the Tiber named (8.55)."""),
(149, 'infra.',
 "us if they drive out, nothing to be wanting they believe\nbut that all Hesperia utterly under their yoke they send\nand the sea which above they hold, and which washes below.",
 "if they drive us out, they believe nothing will stop them from putting the whole of Hesperia under their yoke and holding the sea that washes it above and the sea that washes it below.",
 """'nos si pellant', 'if they should drive us out', present subjunctive in a condition within their thought. 'nihil afore… quin', 'that nothing will be wanting (to stop them) from…': 'afore' = 'afuturum esse', the future infinitive of 'absum', and 'quin' with the subjunctive follows a negative of doubt or hindrance. 'Hesperiam', 'the western land', Italy; elided 'omn(em) Hesperiam'. 'sub iuga mittant', 'send under the yoke', the old sign of conquest. 'mare quod supra… quodque adluit infra', 'the sea which (washes) above and which washes below': the Romans called the Adriatic the Upper Sea and the Tyrrhenian the Lower, so the whole peninsula is meant. 'teneant', 'they may hold'. 'adluit' is Greenough's spelling of 'alluit'. Elision 'quodqu(e) adluit'."""),
(151, 'iuventus.”',
 "Accept and give a pledge: there are to us strong for war\nhearts, there are spirits, and by deeds tested young men.”",
 "Take my pledge and give me yours: we have hearts that are strong in war, we have courage, and young men proven in action.”",
 """'Accipe daque fidem', 'receive and give faith', the exchange of pledges that makes an alliance; the phrase is old, and Ennius had it (from memory). 'sunt nobis', dative of possession, 'we have', as in the pilot. 'fortia bello pectora', 'hearts strong in war', 'bello' an ablative of respect, the noun held over to the next line. 'sunt… sunt', anaphora. 'rebus spectata', 'tested by events', 'spectatus' of what has been seen and proved. Aeneas closes by offering as much as he asks. Elision 'anim(i) et'. The closing mark ends the speech."""),
(153, 'corpus.',
 "Had spoken Aeneas. He the face and eyes of the speaker\nlong since, and the whole was surveying with his gaze, body.",
 "Aeneas had finished. All the while he spoke, Evander had been studying his face and his eyes, and running his gaze over his whole frame.",
 """A new paragraph in Greenough. 'Dixerat', pluperfect, 'had spoken', a regular close to a speech. 'Ille', Evander. 'loquentis', genitive of the present participle, 'of (him) speaking'. 'iamdudum… lustrabat', 'had long been surveying': 'iamdudum' with the imperfect marks an action going on up to a past moment. 'lustrabat lumine', 'was scanning with his eye', the alliteration slowing the look; 'lumen', 'light', is often 'eye' in verse. He is looking for Anchises in the son. Elisions 'Ill(e) os', 'iamdud(um) et'."""),
(155, 'libens!',
 "Then thus a few words he returns: “How you, bravest of the Teucrians,\nI receive and recognise, gladly!",
 "Then he answers in few words: “How gladly I welcome you, bravest of the Trojans, and how gladly I know you!",
 """'pauca refert', 'he replies a few words', a contrast with Aeneas's long plea. 'Ut', 'how!', exclamatory, with the indicative. 'Teucrum', old genitive plural (= 'Teucrorum'), the 'eu' one syllable. 'agnosco', 'I recognise': the son has his father's look. 'libens', 'willing', with the force of an adverb, 'gladly'. Elision 'accipi(o) agnoscoque'."""),
(156, 'recordor!',
 "How the words of your father\nand the voice of great Anchises and his face I recall!",
 "How well I remember the words of your father, the voice and the face of great Anchises!",
 """'Ut', 'how!', again, a second exclamation (anaphora). 'parentis… Anchisae magni', 'of your father… great Anchises', 'Anchisae' the genitive of the Greek name in '-es'. 'voltum' is Greenough's spelling of 'vultum', 'face'. 'recordor', deponent, 'I recall', with three objects. Anchises died in Sicily (end of Book III); Evander knew him as a young man."""),
(159, 'finis.',
 "For I remember, of Hesione visiting the realm, his sister,\nthe son of Laomedon, Priam, Salamis making for,\nonward of Arcadia the cold to visit bounds.",
 "For I remember how Priam, son of Laomedon, on his way to Salamis to see the kingdom of his sister Hesione, came on to visit the cold country of Arcadia.",
 """'memini' with the accusative and present infinitive, 'Priamum… invisere', 'I remember Priam visiting': with 'memini' the present infinitive is used of what one saw oneself. 'Hesionae… sororis', 'of his sister Hesione': Priam's father Laomedon cheated Hercules of the reward for saving her from a sea-monster, and Hercules took Troy and gave her to his comrade Telamon, king of Salamis (the off-shore island near Athens), to whom she bore Teucer; so the tale of Hercules is in the background even here. 'Laomedontiaden', the Greek accusative of the patronymic, 'son of Laomedon'. 'Salamina', Greek accusative of 'Salamis'. 'protinus', 'onward'. 'finis', accusative plural in '-is', 'territory'. The visit to Arcadia is not in Homer, and the commentators know no other source (from memory). Elision 'memin(i) Hesionae'. Line 158 is all dactyls."""),
(163, 'Anchises:',
 "Then for me first was clothing my cheeks with its flower youth,\nand I was marvelling at the Teucrian leaders, I marvelled too at the very\nson of Laomedon, but taller than all walked\nAnchises:",
 "I was then in the first bloom of youth, with the down upon my cheeks, and I gazed in wonder at the Trojan chieftains, and at the son of Laomedon himself; but taller than all of them walked Anchises:",
 """'mihi… genas', 'my cheeks', a dative of reference with a part of the body. 'prima… iuventas', 'first youth', 'iuventas' a poetic form of 'iuventus', the name of the goddess of youth. 'vestibat', an old form of the imperfect, 'vestiebat', 'was clothing'; 'flore', 'with the bloom', the first down of the beard. 'mirabarque… mirabar', the verb repeated as his wonder grows; 'Teucros' here an adjective, 'Trojan'. 'Laomedontiaden' again, of Priam. 'cunctis', ablative of comparison, 'than all'. 'ibat', 'was walking', 'went'. 'Anchises' held over to the start of the line, standing out from the rest."""),
(164, 'dextram.',
 "my mind with youthful burned with love\nto address the man and to his right hand to join my right.",
 "my heart burned with a young man's longing to speak with him and to clasp his right hand in mine.",
 """'mihi mens', 'the mind in me', dative of reference. 'ardebat' with the infinitives 'compellare… coniungere', 'burned to address… to join', a poetic construction. 'iuvenali… amore', 'with youthful love', admiration, framing the rest of the clause. 'dextrae… dextram', 'right hand to right hand', the same word in two cases (polyptoton), the handclasp of friendship, as at 124. Elisions 'iuvenal(i) ardebat', 'vir(um) et'."""),
(165, 'duxi.',
 "I approached, and eager to Pheneus's beneath the walls led him.",
 "I went up to him, and in my eagerness brought him home beneath the walls of Pheneus.",
 """'Accessi', 'I went up to him'. 'cupidus', 'eager', an adjective where English would use an adverb. 'Phenei', genitive of 'Pheneus', a town in the north of Arcadia below Mount Cyllene, Evander's old home; three syllables, 'Phe-ne-i'. 'duxi', with the object, Anchises, understood: as host. Elision 'Access(i) et'."""),
(168, 'Pallas.',
 "He to me a splendid quiver and Lycian arrows,\non leaving, and a cloak with gold gave interwoven,\nand bridles, a pair, my which now has, golden, Pallas.",
 "When he left he gave me a splendid quiver with Lycian arrows, a cloak shot through with gold, and a pair of golden bridles, which are now my Pallas's.",
 """Guest-gifts given at parting are Homeric: Glaucus and Diomedes recall the friendship of their grandfathers and exchange armour (Iliad 6, from memory). 'insignem', 'remarkable', 'splendid'. 'Lycias… sagittas', 'Lycian arrows': Lycia in Asia Minor, an ally of Troy, was famous for its archers. 'discedens', 'as he left'. 'chlamydem', accusative of 'chlamys', a Greek riding cloak; 'auro… intertextam', 'interwoven with gold', the participle held to the end. Line 167 has a spondee in the fifth foot and ends on a four-syllable word, a 'spondaic' line. 'frena… bina', 'a pair of bridles', 'bini' a distributive. 'quae' is held back: 'which my Pallas now has'. 'meus… Pallas', 'my Pallas', a father's affection. Elisions 'mih(i) insignem', 'chlamydemqu(e) auro'."""),
(171, 'iuvabo.',
 "So both the one which you seek is joined by me in a treaty, right hand,\nand the light, as soon as to the lands itself tomorrow's returns,\nwith help, glad, I will send you away and with resources will aid you.",
 "So the right hand you ask for is joined to yours in a treaty, and as soon as tomorrow's light returns to the earth, I will send you on your way glad of my help, and I will aid you with all I have.",
 """'Ergo', 'therefore': for the sake of Anchises. 'quam petitis… dextra', 'the right hand which you seek', the antecedent placed inside the relative clause. 'iuncta est mihi', 'is joined by me', 'mihi' a dative of the agent with the perfect passive: the alliance is made in a single sentence. 'et… et', 'both… and'. 'cum primum', 'as soon as'. 'crastina', 'of tomorrow', an adjective agreeing with 'lux', split from it. 'reddet', future; 'dimittam… iuvabo', futures. 'auxilio laetos', 'glad with help'. 'opibus', 'with my resources'. Elision 'dimitt(am) opibusque'."""),
(174, 'mensis.”',
 "Meanwhile these rites, since here you have come as friends,\nyearly, which to put off is unlawful, celebrate with goodwill\nwith us, and already now to your allies' grow used to tables.”",
 "Meanwhile, since you have come here as friends, join us gladly in keeping these yearly rites, which it would be sinful to put off, and make yourselves at home from this moment at the tables of your allies.”",
 """'sacra haec… annua', 'these yearly rites', split across the line. 'quando', 'since'. 'amici', predicative, 'as friends'. 'quae differre nefas', supply 'est', 'which it is impious to postpone'. 'celebrate', 'celebrate', imperative plural. 'faventes', 'with good will': 'favete' ('be propitious', i.e. keep holy silence) was the call at a Roman sacrifice, and the word has its ritual ring here. 'adsuescite' (= 'assuescite') with the dative 'mensis', 'grow used to the tables', 'sociorum', 'of your allies'. Elisions 'sacr(a) haec', 'nobisc(um) et'. The closing mark ends Evander's speech."""),
(178, 'acerno.',
 "These things when said, the feast he orders and the removed to be put back,\nthe cups, and on a grassy the men he seats himself bench,\nand as foremost, on a couch and with a shaggy hide of a lion,\nhe receives Aeneas and to a throne invites him, of maple.",
 "When he had spoken, he ordered the food and the cups that had been cleared away to be set out again; with his own hand he seated the men on a bench of turf, and Aeneas, as chief guest, he received on a couch spread with a shaggy lion's hide, and invited him to a chair of maple.",
 """A new paragraph in Greenough. 'Haec ubi dicta', supply 'sunt', 'when these words were spoken', the verb left out as so often. 'iubet… reponi', 'orders to be put back', 'dapes… et sublata… pocula', 'the feast and the cups (that had been) taken away' when the alarm broke the meal off (110). 'gramineo… sedili', 'on a grassy seat', a bench of turf, framing 'viros locat ipse'. 'praecipuum', 'specially', 'as chief guest', agreeing with 'Aenean'. 'toro', 'on a couch'. 'villosi pelle leonis', 'with the hide of a shaggy lion', the beast whose skin is Hercules's own emblem; Aeneas carried his father out of Troy with a lion's skin over his shoulders (2.722). 'Aenean', Greek accusative. 'solio… acerno', 'on a chair of maple': plain Arcadian furniture fit for a king. Elision 'tor(o) et'."""),
(181, 'ministrant.',
 "Then chosen young men eagerly and of the altar the priest\nthe flesh, roasted, bring of bulls, and load in baskets\nthe gifts of laboured Ceres, and Bacchus serve.",
 "Then chosen youths and the priest of the altar vie with one another in bringing the roasted flesh of the bulls; they heap the baskets with bread, the gift of Ceres won by toil, and serve the wine.",
 """'certatim', 'vying with each other'. 'arae sacerdos', 'the priest of the altar': at Rome the cult was kept by two families, the Potitii and Pinarii (named at 269–270). 'viscera', not just the inner organs but all the flesh of the victim (Servius, from memory). 'tosta', 'roasted'. 'onerant… canistris', 'they load in baskets', 'canistris' an ablative of place. 'dona laboratae Cereris', 'the gifts of laboured Ceres', bread, the corn-goddess's gift won by the farmer's work; 'Bacchum', 'Bacchus', wine. Naming a god for his gift is a figure (metonymy) you will meet constantly: Ceres for bread, Bacchus for wine, Vulcan for fire. Elision 'certatim araeque'."""),
(183, 'extis.',
 "Feeds Aeneas, at the same time, and the Trojan youth,\non an unbroken chine of an ox and on purifying entrails.",
 "Aeneas and the Trojan youth with him feast on the long chine of an ox and on the entrails of the sacrifice.",
 """'Vescitur', 'feeds on', a deponent with the ablative ('tergo… extis'); singular verb, with the second subject added after it, 'simul et Troiana iuventus'. 'perpetui tergo bovis', 'the back of an unbroken ox', the whole chine, the portion of honour in Homer, as when Ajax is honoured with 'the long chine' after his duel with Hector (Iliad 7, from memory). 'lustralibus extis', 'the entrails of the purifying sacrifice'. 'Aeneas' with 'Ae' one syllable, as always."""),
(188, 'inposuit:',
 "After was banished hunger and the love checked of eating,\nKing Evander says: “Not these solemn rites on us,\nthese according to custom feasts, this of so great a deity altar\nan empty superstition, and of the ancient ignorant gods,\nhas imposed:",
 "When hunger was driven off and the desire for food was stayed, King Evander said: “These solemn rites, this feast held by custom, this altar of so great a power were not laid on us by empty superstition, knowing nothing of the gods of old:",
 """A new paragraph in Greenough. 'exempta (est)… compressus (est)', 'was taken away… was checked', the verbs left out. The line echoes the Homeric formula for the end of a meal ('when they had put away the desire of drink and food', from memory), which Virgil used at 1.216, 'Postquam exempta fames epulis'. 'edendi', gerund, 'of eating'. 'Non haec… has… hanc', 'these… these… this', three objects, each with its demonstrative (a tricolon with anaphora). 'nobis', dative with 'inposuit' (Greenough's spelling of 'imposuit'), 'laid on us'. 'tanti numinis', 'of so great a deity'. 'vana superstitio', 'empty superstition', fear of the gods without knowledge. 'veterum… ignara deorum', 'ignorant of the gods of old', the genitive with an adjective of knowing. What follows is an aetiology, a story told to explain a rite: why Rome worshipped Hercules at the Ara Maxima."""),
(189, 'honores.',
 "from cruel, Trojan guest, dangers\nsaved we sacrifice and deserved renew honours.",
 "it is because we were saved, my Trojan guest, from cruel perils that we make these offerings and renew the honours he has earned.",
 """'saevis… periclis', 'from cruel dangers', an ablative of separation with 'servati'; 'periclis' is the shorter form of 'periculis', as at 8.73. 'hospes Troiane', vocative, set in the middle. 'servati', 'saved', with 'nos' understood. 'facimus', 'we sacrifice': 'facere' is the ordinary Latin word for performing a sacrifice. 'meritos… honores', 'deserved honours', framing the clause. 'novamus', 'we renew', year by year."""),
(192, 'ruinam.',
 "Now first, with rocks overhung, this look at cliff,\nhow scattered far the masses, and deserted of the mountain\nstands the house, and the crags a huge have drawn down ruin.",
 "First, look at this cliff hanging with rocks: see how the masses of stone are flung far and wide, how the mountain dwelling stands empty, and the crags have fallen in vast ruin.",
 """'Iam primum', 'now first', 'to begin with'. 'saxis suspensam… rupem', 'a cliff overhung with rocks', the steep side of the Aventine, the hill across the valley from the Palatine; 'hanc… aspice', 'look at this', as Evander points. 'ut', 'how', exclamatory, with the indicatives 'stat' and 'traxere' ('disiectae (sunt)'). 'disiectae… moles', 'masses torn apart', its 'i' a consonant, 'dis-yec-tae'. 'deserta… montis… domus', 'the deserted home of the mountain', the empty cave. 'traxere' = 'traxerunt', 'have drawn (with them)'. 'ingentem… ruinam', 'a huge fall', framing. Evander points to the ruin left when the cave was broken open, as the next part will tell."""),
(195, 'radiis;',
 "Here a cave was, in a vast withdrawn recess,\nwhich of half-human Cacus the shape, dreadful, held,\nto the sun's unreachable rays;",
 "Here was a cave, reaching far back into vast depths, the lair of the dreadful half-human form of Cacus, a place the rays of the sun never reached;",
 """'spelunca… summota', 'a cave set back', 'vasto… recessu', 'in a vast recess', ablative of description. 'semihominis', 'half-man', genitive: its 'i' is said as a consonant, 'sem-yo-mi-nis', so that the word will fit the verse. Cacus is a fire-breathing monster, son of Vulcan (198); his name looks like the Greek 'kakos', 'evil', and the ancients made the connection (from memory). In Livy's version (1.7, from memory) he is a fierce shepherd, not a monster; the story is told also by Propertius (4.9) and by Ovid (Fasti 1, from memory). 'facies… dira', 'the dread shape', Cacus himself, the subject of 'tenebat'; 'quam' is the cave. 'solis inaccessam radiis', 'unreached by the sun's rays', 'radiis' a dative with the adjective."""),
(197, 'tabo.',
 "and always with fresh\nslaughter was warm the ground, and on the doors, fastened, the proud,\nthe faces of men with grim were hanging, pale, gore.",
 "the ground was always warm with fresh slaughter, and nailed to the insolent doors hung the faces of men, pale and fouled with gore.",
 """'recenti caede', 'with fresh slaughter', split over the line. 'tepebat', 'was warm'. 'foribus… adfixa superbis', 'fastened to the proud doors', 'foribus' a dative with the compound 'adfixa' (Greenough's spelling of 'affixa'); 'superbis', 'proud', with the trophies they bore. 'ora virum', 'the faces of men', 'virum' the old genitive plural again (= 'virorum'). 'tristi… tabo', 'with grim gore', the decaying matter of the dead, framing the line. 'pendebant pallida', 'hung pale', alliteration."""),
(199, 'ferebat.',
 "To this monster Vulcan was father: his black\nfrom his mouth spewing fires, with great himself bulk he bore.",
 "Vulcan was the father of this monster: it was his father's black fires that he belched from his mouth as he moved his huge bulk along.",
 """'Huic monstro', dative of possession, 'this monster had Vulcan for father'. 'Volcanus' is Greenough's spelling of 'Vulcanus'. 'illius', 'his', Vulcan's: the son breathes his father's fire. 'atros… ignis', 'black fires', smoky flames, 'ignis' accusative plural in '-is'. 'vomens', 'vomiting'. 'magna se mole ferebat', 'he carried himself with great bulk', he moved his vast body."""),
(201, 'dei.',
 "Brought to us too, at last, as we wished, time\nhelp and the coming of a god.",
 "To us too, after long prayers, time at last brought help, in the coming of a god.",
 """'et nobis', 'to us also', as to others in need. 'aliquando', 'at length'. 'optantibus', dative of the participle agreeing with 'nobis', 'to us praying for it'. 'aetas', 'time', the passing years. 'auxilium adventumque dei', 'help and the coming of a god', two nouns for one idea (hendiadys), 'the help of a god's coming'. 'dei': Hercules, a god now and worshipped as one, though he came as a mortal hero. Elision 'aliquand(o) optantibus', 'auxili(um) adventumque'."""),
(204, 'tenebant.',
 "For the greatest avenger,\nwith the threefold Geryon's death and spoils proud,\nAlcides was at hand, and bulls this way as victor he was driving,\nhuge, and the valley the cattle and the river were filling.",
 "For the mightiest of avengers, Alcides, proud from the slaughter and the spoils of three-bodied Geryon, came our way, driving his huge bulls here in triumph, and the cattle filled the valley and the riverside.",
 """'maximus ultor', 'greatest avenger', here printed 'maximus' where 136 printed 'maxumus' (Greenough's spelling varies), and a hint at the name of the altar, the Ara Maxima. 'tergemini… Geryonae', 'of triple Geryon', the giant with three bodies who lived on the island of Erythea in the far west near Gades (Cadiz); the theft of his cattle was the tenth of Hercules's labours, and he drove them home through Spain, Gaul and Italy. 'Geryonae' is the genitive of a Greek form in '-es'. 'nece… spoliisque', ablatives of cause with 'superbus', 'proud of the death and the spoils'. 'Alcides', 'descendant of Alceus', Amphitryon's father, another patronymic of Hercules. 'hac', adverb, 'this way'. 'victor', predicative. 'ingentis', accusative plural in '-is', with 'tauros', held over to 204. 'vallem… amnemque', 'the valley and the river', double '-que': the low ground between Palatine and Aventine, by the Tiber, where the Forum Boarium, the 'cattle market', later stood."""),
(208, 'iuvencas;',
 "But with frenzies Cacus's mind, wild, so that nothing undared\nor unattempted, of crime or of guile, should have been,\nfour from the stalls of outstanding body bulls\ndrove off, as many of surpassing beauty heifers;",
 "But Cacus, his mind made savage by madness, so that no crime or trickery should be left undared or untried, drove off from the pens four bulls of splendid build and as many heifers of surpassing beauty;",
 """'furiis', 'with frenzies', an ablative of cause with 'effera', 'wild'; the Latin Library prints 'furis', genitive of 'fur', 'thief': 'the wild mind of Cacus the thief', a reading many editors prefer (from memory), and a real change of sense. 'mens effera', the subject of 'avertit': the wild mind does the deed. 'nequid' (= 'ne quid') begins a clause of purpose, 'so that nothing should be left undared'; 'inausum… intractatum', 'undared… untried'; 'sceleris… doli', partitive genitives with 'quid', '-ve… -ve' 'or… or'. 'fuisset', pluperfect subjunctive, looking at the whole range of crime as done. 'praestanti corpore', 'forma superante', ablatives of description, set in parallel. 'avertit', 'turned aside', the regular word for driving off stolen cattle. 'totidem', 'as many'."""),
(211, 'opaco:',
 "and these, so that no tracks should be with feet straight,\nby the tail into the cave dragged, and with turned of their ways\nsigns, carried off, in the rock he was hiding, dark:",
 "and so that there should be no tracks with the hooves pointing forward, he dragged them into the cave by their tails, and with the marks of their path turned back to front, he kept his plunder hidden in the dark rock:",
 """'nequa' = 'ne qua', 'so that no…', purpose. 'forent' = 'essent'. 'pedibus… rectis', 'with feet straight forward', ablative of description: tracks pointing towards the cave. 'cauda… tractos', 'dragged by the tail', backwards, so the prints point away from the cave. The trick is old: the infant Hermes, Evander's father, stole Apollo's cattle and drove them backwards (Homeric Hymn to Hermes, from memory). 'versis… viarum indiciis', ablative absolute, 'the signs of the paths reversed'. 'raptos', 'stolen', with 'hos'; the Latin Library has 'raptor', 'he, the robber, hid them', which makes Cacus the subject named, a change of sense. 'saxo… opaco', 'in the dark rock', ablative of place. 'occultabat', imperfect, 'kept hidden'. Elision 'caud(a) in'."""),
(212, 'ferebant.',
 "to one searching, no to the cave signs were leading.",
 "anyone who looked would find no tracks that led to the cave.",
 """'quaerenti', dative of the present participle, 'for one seeking', a dative of reference with no noun: 'to a searcher'. 'nulla… signa', 'no signs', framing 'ad speluncam'. 'ferebant', 'led', the sense of a road or tracks that 'carry' you somewhere."""),
(216, 'relinqui.',
 "Meanwhile, when already from the stalls the well-fed he was moving,\nthe son of Amphitryon, the herds, and departure was preparing,\nat the going lowed the cattle, and all with complaints\nwas filled the grove, and the hills with clamour were left.",
 "Meanwhile, when the son of Amphitryon was already moving his well-fed herds out of their pens and making ready to go, the cattle lowed as they left; the whole grove was filled with their complaints, and they left the hills behind with loud bellowing.",
 """The print has 'Amphytrioniades', a misprint for 'Amphitryoniades', corrected here: the 'i' and 'y' have changed places (103 prints the name correctly, 'Amphitryoniadae', and the Latin Library has 'Amphitryoniades'). t keeps the print, since t must match the pinned source. 'cum… moveret… pararet', 'when he was moving… and preparing', imperfect subjunctives in a 'cum' clause of circumstance. 'stabulis', ablative of separation, 'from the stalls'. 'saturata… armenta', 'the well-fed herds', framing. 'abitum', 'departure'. 'discessu', 'at the leaving', ablative of time. 'mugire… impleri… relinqui', historical infinitives: in vivid narrative Latin can use the present infinitive with a nominative subject in place of an imperfect indicative, 'the cattle lowed… the grove was filled… the hills were left'. You will meet this again. 'querelis', 'with complaints', the lowing taken as grief. Elisions 'armenta abitumque', 'atqu(e) omne'."""),
(218, 'fefellit.',
 "Returned one of the cows the sound, and in the vast beneath cave\nlowed, and Cacus's hope, though guarded, cheated.",
 "One of the heifers answered their call, lowed from deep inside the huge cave, and, closely as she was guarded, betrayed the hopes of Cacus.",
 """The print has 'reddidit', lowercase after the full stop that ends 216, a misprint for 'Reddidit', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'reddidit… vocem', 'gave back the sound', answered the lowing of the herd. 'una boum', 'one of the cattle', 'boum' the genitive plural of 'bos' (two syllables); she is one of the four heifers. 'vasto… sub antro', 'beneath the vast cave', inside it. 'mugiit', perfect of 'mugio', three syllables. 'custodita', 'though guarded', a participle with concessive force. 'fefellit', 'deceived', 'cheated', the reduplicated perfect of 'fallo'. Cacus's hope is betrayed by a single animal; what Hercules does when he hears it follows in the next part."""),
]

P = A.part('aeneid-058'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
